script:
// Manometer: 0 cmH2O at y=478, 7.2 px per cmH2O. 1 mmHg ~ 1.36 cmH2O, so 22 mmHg ~ 29.9 cmH2O.
const TX = 394, Y0 = 478, PX = 7.2, LO = 7, HI = 18, OP = 22 * 1.36;
const Y = v => Y0 - PX * v;
const RED = "#c0392b", GOOD = "#2a9d8f", ACC = "#e76f51";
const ROW0 = 180, ROWH = 60;
let E = {};
function txt(api, parent, s, a) {
  const t = api.el("text", Object.assign({"dominant-baseline": "central"}, a), parent);
  t.textContent = s; return t;
}
function setup(api) {
  // scale: ticks every 5 cmH2O, labels at 0, 10, 20, 30
  const S = api.$("#scale"), ST = api.$("#scaleTxt");
  for (let v = 0; v <= 35; v += 5) {
    const major = v % 10 === 0;
    api.el("line", {x1: major ? 358 : 366, x2: 375, y1: Y(v), y2: Y(v)}, S);
    if (major && v <= 30) txt(api, ST, String(v), {x: 352, y: Y(v)});
  }
  // normal band 7-18 cmH2O
  api.set(api.$("#band"), {y: Y(HI), height: Y(LO) - Y(HI)});
  api.set(api.$("#bandTxt"), {y: (Y(LO) + Y(HI)) / 2});
  // green ticks for the four unremarkable rows
  E.ticks = [0, 1, 2, 3].map(i => {
    const g = api.el("g", {opacity: 0}, api.$("#ticks"));
    api.el("circle", {cx: 0, cy: 0, r: 15, fill: GOOD}, g);
    api.el("path", {d: "M -6.5 0.5 L -2 5 L 7 -5", fill: "none", stroke: "#ffffff", "stroke-width": 3.2, "stroke-linecap": "round", "stroke-linejoin": "round"}, g);
    return {g, x: 262, y: ROW0 + ROWH * i + 31};
  });
  // red "raised" pill (replaces the grey ?)
  E.raised = api.el("g", {opacity: 0}, api.$("#ticks"));
  api.el("rect", {x: -44, y: -15, width: 88, height: 30, rx: 15, fill: RED}, E.raised);
  txt(api, E.raised, "↑ raised", {x: 0, y: 1, "text-anchor": "middle", fill: "#ffffff", "font-size": 17, "font-weight": 800});
  // level marker at 30
  E.marker = api.$("#marker");
  api.set(E.marker, {opacity: 0});
  const my = Y(30);
  api.el("line", {x1: 405, x2: 418, y1: my, y2: my, stroke: ACC, "stroke-width": 2.5, "stroke-dasharray": "3 3"}, E.marker);
  E.mPath = api.el("path", {d: "M 418 " + my + " L 427 " + (my - 8) + " L 427 " + (my + 8) + " Z", fill: ACC}, E.marker);
  E.mRect = api.el("rect", {x: 426, y: my - 14, width: 44, height: 28, rx: 9, fill: ACC}, E.marker);
  txt(api, E.marker, "30", {x: 448, y: my + 1, "text-anchor": "middle", fill: "#ffffff", "font-size": 17, "font-weight": 800});
  // conversion chip near the tube top, sized to its text
  E.chip = api.$("#chip");
  const bg = api.el("rect", {rx: 14, fill: "#fff1ec", stroke: "#f2b8a6", "stroke-width": 1.5}, E.chip);
  const a = txt(api, E.chip, "22 mmHg × 1.36", {"text-anchor": "middle", fill: "#b23a1e", "font-size": 16, "font-weight": 800});
  const b = txt(api, E.chip, "≈ 30 cmH₂O", {"text-anchor": "middle", fill: "#b23a1e", "font-size": 16, "font-weight": 800});
  const w = Math.ceil(Math.max(a.getBBox().width, b.getBBox().width)) + 26;
  const cx = Math.min(430 + w / 2, 600 - w / 2), cy = 200;
  api.set(bg, {x: cx - w / 2, y: cy - 28, width: w, height: 56});
  api.set(a, {x: cx, y: cy - 11}); api.set(b, {x: cx, y: cy + 12});
  api.set(E.chip, {opacity: 0});
  E.fluid = api.$("#fluid"); E.red = api.$("#fluidRed"); E.men = api.$("#meniscus");
  E.band = api.$("#band"); E.box = api.$("#opBox"); E.val = api.$("#opVal"); E.q = api.$("#qMark");
}
function render(t, api) {
  // Beat 1 (0-2400): green ticks pop in one after another from 300 ms
  E.ticks.forEach((k, i) => {
    const p = api.seg(t, 300 + 400 * i, 650 + 400 * i, "back_out");
    api.set(k.g, {opacity: Math.min(1, p * 2), transform: "translate(" + k.x + " " + k.y + ") scale(" + Math.max(0.01, p) + ")"});
  });
  // Beat 2 (2400-5200): chip + marker at 2500, column rises to 22 x 1.36 cmH2O
  const c = api.seg(t, 2500, 2950, "ease_out");
  api.set(E.chip, {opacity: c, transform: "translate(" + (1 - c) * 18 + " 0)"});
  api.set(E.marker, {opacity: api.seg(t, 2600, 3000, "ease_out")});
  const lvl = OP * api.seg(t, 2550, 4400, "ease_in_out");
  const yl = Y(lvl);
  api.set(E.fluid, {y: yl, height: 500 - yl});
  api.set(E.men, {d: "M 383 " + yl.toFixed(1) + " Q 394 " + (yl + 4).toFixed(1) + " 405 " + yl.toFixed(1)});
  const hi = api.seg(t, 2500, 2800, "ease_out");
  // Beat 3 (5200-8000): part above 18 turns red, band pulses once, row marked raised
  const r = api.seg(t, 5200, 5700, "ease_out");
  const top = Math.min(yl, Y(HI));
  api.set(E.red, {y: top, height: Y(HI) - top, opacity: 0.78 * r});
  api.set(E.men, {stroke: api.mixColor("#5aa6c9", RED, r)});
  const pulse = Math.sin(Math.PI * api.seg(t, 5200, 6100, "ease_in_out"));
  api.set(E.band, {"stroke-width": 2 + 3.5 * pulse, "fill-opacity": 0.16 + 0.14 * pulse});
  api.set(E.box, {"stroke-width": 2 + 1.5 * hi, stroke: api.mixColor(ACC, RED, r), fill: api.mixColor("#fff5f0", "#fdebea", r)});
  api.set(E.val, {fill: api.mixColor(api.mixColor("#16323a", "#b23a1e", hi), RED, r)});
  api.set(E.mPath, {fill: api.mixColor(ACC, RED, r)}); api.set(E.mRect, {fill: api.mixColor(ACC, RED, r)});
  api.set(E.q, {opacity: 1 - api.seg(t, 5200, 5400, "ease_out")});
  const p = api.seg(t, 5250, 5700, "back_out");
  api.set(E.raised, {opacity: Math.min(1, p * 2), transform: "translate(228 484) scale(" + Math.max(0.01, p) + ")"});
}
